1	/**
2	 * Seed sensible per-game pricing tiers (GamePlan rows).
3	 *
4	 * For each tier we pick:
5	 *   - basePlanId   = the smallest active VPS Plan whose ramMB >= the tier's ramMB
6	 *                    (falls back to the largest plan if none is big enough).
7	 *   - osTemplateId = that game's OsTemplate (family=<game>, category=APPLICATION),
8	 *                    if one exists; otherwise null (deploy resolves it at runtime).
9	 *
10	 * Idempotent: dedupes by (gameFamily, name) and upserts.
11	 *
12	 * Run: cd /opt/nxeon && npx tsx prisma/seed-gameplans.ts
13	 */
14	import { PrismaClient } from "@prisma/client";
15	
16	const db = new PrismaClient();
17	
18	type TierSpec = {
19	  gameFamily: string;
20	  name: string;
21	  ramMB: number;
22	  cpuCores: number;
23	  diskGB: number;
24	  slots: number;
25	  priceCents: number;
26	  featured?: boolean;
27	};
28	
29	// Retail prices in cents, monthly term. RAM/slots/price differ per game.
30	const TIERS: TierSpec[] = [
31	  // Minecraft — light, scales by player count.
32	  { gameFamily: "minecraft", name: "Minecraft — 2 GB / 10 slots", ramMB: 2048, cpuCores: 2, diskGB: 20, slots: 10, priceCents: 499 },
33	  { gameFamily: "minecraft", name: "Minecraft — 4 GB / 20 slots", ramMB: 4096, cpuCores: 2, diskGB: 30, slots: 20, priceCents: 899, featured: true },
34	  { gameFamily: "minecraft", name: "Minecraft — 8 GB / 50 slots", ramMB: 8192, cpuCores: 3, diskGB: 50, slots: 50, priceCents: 1599 },
35	
36	  // Valheim — RAM-hungry world simulation.
37	  { gameFamily: "valheim", name: "Valheim — 4 GB / 10 players", ramMB: 4096, cpuCores: 2, diskGB: 30, slots: 10, priceCents: 999 },
38	  { gameFamily: "valheim", name: "Valheim — 8 GB / 20 players", ramMB: 8192, cpuCores: 3, diskGB: 50, slots: 20, priceCents: 1699, featured: true },
39	
40	  // Rust — needs the most RAM & CPU, big populations.
41	  { gameFamily: "rust", name: "Rust — 4 GB / 40 slots", ramMB: 4096, cpuCores: 2, diskGB: 40, slots: 40, priceCents: 1299 },
42	  { gameFamily: "rust", name: "Rust — 6 GB / 60 slots", ramMB: 6144, cpuCores: 3, diskGB: 60, slots: 60, priceCents: 1799, featured: true },
43	  { gameFamily: "rust", name: "Rust — 10 GB / 150 slots", ramMB: 10240, cpuCores: 4, diskGB: 80, slots: 150, priceCents: 2999 },
44	
45	  // Palworld — heavy, small-ish parties.
46	  { gameFamily: "palworld", name: "Palworld — 8 GB / 8 players", ramMB: 8192, cpuCores: 3, diskGB: 50, slots: 8, priceCents: 1499 },
47	  { gameFamily: "palworld", name: "Palworld — 16 GB / 32 players", ramMB: 16384, cpuCores: 4, diskGB: 80, slots: 32, priceCents: 2799, featured: true },
48	
49	  // CS2 — competitive FPS, modest RAM.
50	  { gameFamily: "cs2", name: "CS2 — 2 GB / 12 slots", ramMB: 2048, cpuCores: 2, diskGB: 40, slots: 12, priceCents: 699 },
51	  { gameFamily: "cs2", name: "CS2 — 4 GB / 24 slots", ramMB: 4096, cpuCores: 3, diskGB: 50, slots: 24, priceCents: 1199, featured: true },
52	
53	  // Terraria — lightweight sandbox.
54	  { gameFamily: "terraria", name: "Terraria — 2 GB / 8 players", ramMB: 2048, cpuCores: 1, diskGB: 20, slots: 8, priceCents: 449 },
55	  { gameFamily: "terraria", name: "Terraria — 4 GB / 16 players", ramMB: 4096, cpuCores: 2, diskGB: 30, slots: 16, priceCents: 799, featured: true },
56	];
57	
58	async function main() {
59	  const plans = await db.plan.findMany({ where: { active: true }, orderBy: { ramMB: "asc" } });
60	  if (plans.length === 0) {
61	    throw new Error("No active VPS plans found — run the main seed first (npx prisma db seed).");
62	  }
63	  const largest = plans[plans.length - 1];
64	
65	  // Cache the first game image per family.
66	  const imageByFamily = new Map<string, string>();
67	  for (const spec of TIERS) {
68	    if (imageByFamily.has(spec.gameFamily)) continue;
69	    const os = await db.osTemplate.findFirst({
70	      where: { family: spec.gameFamily, category: "APPLICATION" },
71	      orderBy: { sortOrder: "asc" },
72	    });
73	    imageByFamily.set(spec.gameFamily, os?.id ?? "");
74	  }
75	
76	  let created = 0;
77	  let updated = 0;
78	  let sortByGame = new Map<string, number>();
79	
80	  for (const spec of TIERS) {
81	    const basePlan = plans.find((p) => p.ramMB >= spec.ramMB) ?? largest;
82	    const osId = imageByFamily.get(spec.gameFamily) || null;
83	    const sortOrder = (sortByGame.get(spec.gameFamily) ?? 0);
84	    sortByGame.set(spec.gameFamily, sortOrder + 1);
85	
86	    const data = {
87	      gameFamily: spec.gameFamily,
88	      name: spec.name,
89	      ramMB: spec.ramMB,
90	      cpuCores: spec.cpuCores,
91	      diskGB: spec.diskGB,
92	      slots: spec.slots,
93	      priceCents: spec.priceCents,
94	      termMonths: 1,
95	      basePlanId: basePlan.id,
96	      osTemplateId: osId,
97	      featured: spec.featured ?? false,
98	      active: true,
99	      sortOrder,
100	    };
101	
102	    // Dedupe by (gameFamily, name) — no DB unique constraint exists on the pair.
103	    const existing = await db.gamePlan.findFirst({
104	      where: { gameFamily: spec.gameFamily, name: spec.name },
105	    });
106	    if (existing) {
107	      await db.gamePlan.update({ where: { id: existing.id }, data });
108	      updated++;
109	    } else {
110	      await db.gamePlan.create({ data });
111	      created++;
112	    }
113	    console.log(
114	      `  ${spec.gameFamily.padEnd(10)} ${spec.name.padEnd(32)} → base=${basePlan.name} img=${osId ? "yes" : "auto"}`,
115	    );
116	  }
117	
118	  const total = await db.gamePlan.count();
119	  console.log(`\nGamePlans seeded: ${created} created, ${updated} updated. Total in DB: ${total}.`);
120	}
121	
122	main()
123	  .catch((e) => {
124	    console.error(e);
125	    process.exit(1);
126	  })
127	  .finally(async () => {
128	    await db.$disconnect();
129	  });
130

// Server-side quote/creation path for CUSTOM VPS + game-server specs — plain
// module (not "use server"), mirroring lib/order.ts / lib/game-order.ts: it does
// real DB reads/writes but is called FROM "use server" actions that own the
// session check (lib/actions-custom-plan.ts), never exported to the network
// directly (see lib/order.ts's serverLimitError doc for why that split matters).
//
// The pure formula/guardrail math lives in lib/custom-plan-pricing.ts (no DB, so
// the client-side deploy wizards can price a slider move instantly); this file
// wraps it with the DB-backed floor/ceiling/rate resolution and the REAL
// capacity check, then creates the one-off `Plan` (+ `GamePlan`, for a game
// order) row a custom order actually buys.
import { db } from "./db";
import { getSettingInt } from "./settings";
import { extraDiskPerGbCents } from "./disk-expand";
import { capacityCheckRamMB, diskCapacityCheck } from "./capacity";
import { scheduleNode } from "./node-capacity";
import {
  type CustomPlanCeiling,
  type CustomPlanFloor,
  type CustomPlanRates,
  type CustomPlanSpec,
  CUSTOM_PLAN_DEFAULT_CEILING,
  CUSTOM_PLAN_DEFAULT_RATES,
  CUSTOM_PLAN_SORT_ORDER,
  computeCustomPlanPriceCents,
  customPlanName,
  customPlanSlug,
  validateCustomPlanSpec,
} from "./custom-plan-pricing";

export { CUSTOM_PLAN_SORT_ORDER } from "./custom-plan-pricing";

export class CustomPlanError extends Error {}

/**
 * Sort-order convention already established by the ONE pre-existing manual
 * precedent (a "Custom 4 vCPU / 8 GB" Plan row, `sortOrder: 999, active: false`,
 * created before this feature existed for a one-off customer accommodation).
 * `sortOrder < CATALOG_SORT_ORDER_CEILING` is the live premade VPS ladder;
 * 900-903 are NxCloud's backing plans (also `active: false` — see prisma/schema.prisma's
 * comment on `Plan.nxcloudPlans`); `CUSTOM_PLAN_SORT_ORDER` (999) is reserved for
 * one-off custom rows. Both ranges keep `customPlanFloor` below from ever picking
 * up an NxCloud sizing plan or (worse) a PREVIOUS custom order's own Plan row as
 * "Max".
 */
const CATALOG_SORT_ORDER_CEILING = 900;

/**
 * The floor every custom spec must clear: the current top-priced ACTIVE premade
 * VPS plan (today, Max). Read live from the DB rather than hardcoded, so a future
 * catalog change (a new tier added above Max) is picked up automatically with no
 * code change here.
 */
export async function customPlanFloor(): Promise<CustomPlanFloor> {
  const top = await db.plan.findFirst({
    where: { active: true, sortOrder: { lt: CATALOG_SORT_ORDER_CEILING } },
    orderBy: { priceCents: "desc" },
  });
  if (!top) throw new CustomPlanError("No base plan is configured yet — please contact support.");
  return {
    cpuCores: top.cpuCores,
    ramMB: top.ramMB,
    diskGB: top.diskGB,
    priceCents: top.priceCents,
    bandwidthTB: top.bandwidthTB,
  };
}

/** Admin-tunable platform-wide ceiling (lib/settings.ts custom_plan_max_*). */
export async function customPlanCeiling(): Promise<CustomPlanCeiling> {
  const [maxCpuCores, maxRamGB, maxDiskGB] = await Promise.all([
    getSettingInt("custom_plan_max_cpu_cores", CUSTOM_PLAN_DEFAULT_CEILING.maxCpuCores),
    getSettingInt("custom_plan_max_ram_gb", CUSTOM_PLAN_DEFAULT_CEILING.maxRamMB / 1024),
    getSettingInt("custom_plan_max_disk_gb", CUSTOM_PLAN_DEFAULT_CEILING.maxDiskGB),
  ]);
  return { maxCpuCores, maxRamMB: maxRamGB * 1024, maxDiskGB };
}

/** Admin-tunable per-unit rates. Disk reuses `extraDiskPerGbCents()` — the SAME
 *  $/GB the extra-disk upsell already charges on a premade plan — see the
 *  derivation comment on CUSTOM_PLAN_DEFAULT_RATES for why. */
export async function customPlanRates(): Promise<CustomPlanRates> {
  const [perVcpuCents, perRamGbCents, perDiskGbCents] = await Promise.all([
    getSettingInt("custom_plan_per_vcpu_cents", CUSTOM_PLAN_DEFAULT_RATES.perVcpuCents),
    getSettingInt("custom_plan_per_ram_gb_cents", CUSTOM_PLAN_DEFAULT_RATES.perRamGbCents),
    extraDiskPerGbCents(),
  ]);
  return { perVcpuCents, perRamGbCents, perDiskGbCents };
}

export type CustomPlanQuote =
  | { ok: true; floor: CustomPlanFloor; ceiling: CustomPlanCeiling; rates: CustomPlanRates; priceCents: number }
  | { ok: false; reason: string; floor: CustomPlanFloor; ceiling: CustomPlanCeiling };

/** Validate + price a custom spec without creating anything. Never throws — a bad
 *  spec comes back `{ ok: false, reason }` so the wizard can show it inline. */
export async function customPlanQuote(spec: CustomPlanSpec): Promise<CustomPlanQuote> {
  const [floor, ceiling, rates] = await Promise.all([customPlanFloor(), customPlanCeiling(), customPlanRates()]);
  const v = validateCustomPlanSpec(spec, floor, ceiling);
  if (!v.ok) return { ok: false, reason: v.reason, floor, ceiling };

  if (!v.ok) return { ok: false, reason: v.reason, floor, ceiling };
  const priceCents = computeCustomPlanPriceCents(spec, floor, rates);
  return { ok: true, floor, ceiling, rates, priceCents };
}

/**
 * The REAL, pre-checkout capacity check — reuses the exact oversell guards
 * lib/order.ts placeOrder / lib/game-order.ts placeGameOrder already run for
 * every premade-plan order (capacityCheckRamMB mirrors capacityCheck;
 * diskCapacityCheck is the identical function). A custom spec can ask for more
 * RAM than ANY catalog plan, so it must be screened the same way — this is not
 * a second, weaker guard, it's the same one with a raw RAM/disk number instead
 * of a `Plan` row backing it.
 */
export async function customPlanCapacityCheck(spec: CustomPlanSpec): Promise<{ ok: boolean; reason?: string }> {
  const ramOk = await capacityCheckRamMB(spec.ramMB);
  if (!ramOk.ok) return ramOk;
  // Which node WOULD take this — same scheduler VPS/game orders use — so the disk
  // check below runs against a real candidate node's pool, not "any node".
  const node = await scheduleNode(spec.ramMB);
  if (!node) {
    return { ok: false, reason: "No node currently has room for a server this size. Please contact support." };
  }
  return diskCapacityCheck(node.id, spec.diskGB);
}

/** 6-char alnum suffix — matches the one pre-existing manual precedent's slug
 *  shape ("custom-4c8g-hmcebh"). */
function randSuffix(n = 6): string {
  return Math.random().toString(36).slice(2, 2 + n);
}

export type CreatedCustomPlan = {
  id: string;
  name: string;
  cpuCores: number;
  ramMB: number;
  diskGB: number;
  bandwidthTB: number;
  priceCents: number;
  storageTier: string;
};

/**
 * Create ONE real `Plan` row for this exact spec — the same manual-accommodation
 * pattern already proven in production once (see the sort-order doc comment
 * above), now automated. Re-validates guardrails AND capacity from scratch (a
 * client-supplied price/spec is never trusted for money — mirrors every other
 * quote→place split in this codebase) before writing anything.
 *
 * Created INACTIVE with `sortOrder: 999` so it NEVER appears in any catalog query
 * (every page that lists plans filters `active: true` — see
 * app/dashboard/deploy/page.tsx) — it exists solely to be the ONE plan this ONE
 * order's Server row points at. From here on, every downstream money path
 * (lib/order.ts orderQuote/placeOrder, lib/resize.ts, lib/renewal-charge.ts,
 * lib/capacity.ts, admin displays) reads straight off the `Plan` relation exactly
 * like it does for a premade plan — no special-casing needed anywhere else.
 */
export async function createCustomPlan(spec: CustomPlanSpec): Promise<CreatedCustomPlan> {
  const quote = await customPlanQuote(spec);
  if (!quote.ok) throw new CustomPlanError(quote.reason);
  const cap = await customPlanCapacityCheck(spec);
  if (!cap.ok) throw new CustomPlanError(cap.reason ?? "Not enough room for that configuration right now.");

  let lastErr: unknown;
  for (let attempt = 0; attempt < 3; attempt++) {
    try {
      const plan = await db.plan.create({
        data: {
          slug: customPlanSlug(spec, randSuffix()),
          name: customPlanName(spec),
          cpuCores: spec.cpuCores,
          ramMB: spec.ramMB,
          diskGB: spec.diskGB,
          bandwidthTB: quote.floor.bandwidthTB,
          priceCents: quote.priceCents,
          storageTier: "nvme",
          active: false,
          sortOrder: CUSTOM_PLAN_SORT_ORDER,
        },
      });
      return {
        id: plan.id,
        name: plan.name,
        cpuCores: plan.cpuCores,
        ramMB: plan.ramMB,
        diskGB: plan.diskGB,
        bandwidthTB: plan.bandwidthTB,
        priceCents: plan.priceCents,
        storageTier: plan.storageTier,
      };
    } catch (e) {
      lastErr = e; // near-impossible slug collision (6-char random suffix) — retry once or twice
    }
  }
  throw lastErr instanceof Error ? lastErr : new CustomPlanError("Could not create the custom plan — please try again.");
}

export type CreatedCustomGamePlan = {
  plan: CreatedCustomPlan;
  gamePlanId: string;
  name: string;
  priceCents: number;
  slots: number | null;
};

/**
 * Game analogue of `createCustomPlan`: also creates the `GamePlan` tier that
 * rides on top of the freshly-created base `Plan`, exactly like every premade
 * game tier already does (`GamePlan.basePlanId`) — see prisma/seed-gameplans.ts.
 * Priced at the SAME cents the base custom Plan would cost; a custom order has
 * no admin in the loop to hand-pick a cheaper flat game price the way premade
 * tiers sometimes are (see lib/resize.ts's comment on game tiers typically being
 * sold below their base plan's price), so charging exactly the formula price is
 * the safe, unambiguous default.
 */
export async function createCustomGamePlan(opts: {
  spec: CustomPlanSpec;
  gameFamily: string;
  players?: number | null;
}): Promise<CreatedCustomGamePlan> {
  const plan = await createCustomPlan(opts.spec);
  const gp = await db.gamePlan.create({
    data: {
      gameFamily: opts.gameFamily,
      name: `${customPlanName(opts.spec)} (${opts.gameFamily})`,
      ramMB: plan.ramMB,
      cpuCores: plan.cpuCores,
      diskGB: plan.diskGB,
      slots: opts.players ?? null,
      priceCents: plan.priceCents,
      termMonths: 1,
      basePlanId: plan.id,
      active: false,
      sortOrder: CUSTOM_PLAN_SORT_ORDER,
    },
  });
  return { plan, gamePlanId: gp.id, name: gp.name, priceCents: gp.priceCents, slots: gp.slots };
}

