import { GAME_PLAYER_CURVES, recommendedSpecForPlayers, playerSliderMax } from "./lib/game-player-recommend";
import * as fs from "fs";

type Row = { gameFamily: string; name: string; ramMB: number; cpuCores: number; diskGB: number; slots: number; priceCents: number; introPriceCents: number|null; introTermMonths: number|null; featured: boolean; sortOrder: number };

