const FORCE_DIRECTION: Record<string, "top"|"entry"|"headroom-top"> = {
  ats: "headroom-top", ets2: "headroom-top", corekeeper: "headroom-top",
};

const ENTRY_FAMILIES = new Set(["ark","arkasa","armareforger","conan","dayz","dst","eco","empyrion","kf2","l4d2","minecraft","mordhau","sandstorm","sdtd","soulmask","stationeers","tf2","theisle","unturned","vintagestory"]);
const TOP_FAMILIES = new Set(["abioticfactor","barotrauma","bedrock","cs16","dragonwilds","enshrouded","factorio","gmod","icarus","necesse","nightingale","projectzomboid","rust","satisfactory","spaceengineers","squad","sunkenland","vrising"]);
