    p = players ?? Math.round(tN.slots*1.6);
    const spec = recommendedSpecForPlayers(family as any, p);
    ramMB = niceGB(spec.ramMB)*1024;
    cpuCores = Math.max(1, Math.round(spec.cpuCores));
