    ramMB = niceGB(tN.ramMB * Math.max(1.4, stepRatio))*1024;
    cpuCores = Math.min(6, tN.cpuCores + 1);
    diskGB = niceDisk(tN.diskGB * 1.3);
  }
  const ramGB = ramMB/1024;
  let priceCents = Math.round(fit.a + fit.b*ramGB);
  // clamp: must be strictly above tN price if top-direction; strictly below t0 price if entry
  if (direction === "entry") priceCents = Math.min(priceCents, t0.priceCents - 50);
  else priceCents = Math.max(priceCents, tN.priceCents + 50);
  priceCents = round5(priceCents);
  // intro ratio: average existing ratio if intro pricing exists
  const introTiers = tiers.filter(t => t.introPriceCents != null);
  let introPriceCents: number | null = null;
  if (introTiers.length > 0) {
