  if (BOTH_FAMILIES.has(family)) {
    const pE = FORCE_ENTRY_PLAYERS[family];
    results.push(makeTier(family, tiers, "entry", pE));
    results.push(makeTier(family, tiers, "top"));
  } else if (FORCE_DIRECTION[family]) {
